window.RETETE = [{"id": "MD1", "nume": "Omletă cu legume și brânză de vaci, pâine integrală + banană", "scurt": "Omletă cu legume", "grup": "Mic dejun", "masa": "mic dejun 🥚", "timp": "15′", "tine": "nu", "kcal": {"s": 635, "m": 730}, "macro": {"s": {"p": 43, "g": 26, "c": 62, "f": 9}, "m": {"p": 52, "g": 31, "c": 63, "f": 9}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Ouă", "s": "3 buc.", "m": "4 buc.", "sm": "7 buc."}, {"nume": "Brânză de vaci", "s": "100 g", "m": "120 g", "sm": "220 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Spanac", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Roșii", "s": "60 g", "m": "60 g", "sm": "120 g"}, {"nume": "Ciuperci", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Ceapă verde", "s": "20 g", "m": "20 g", "sm": "40 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Pâine integrală", "s": "50 g", "m": "50 g", "sm": "100 g"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Ulei de măsline", "s": "5 g", "m": "5 g", "sm": "10 g"}]}, {"eticheta": "Fruct", "items": [{"nume": "Banană", "s": "1 buc.", "m": "1 buc.", "sm": "2 buc."}]}], "pasi": ["Taie ciupercile felii subțiri, roșiile cuburi, ceapa verde inele; spală spanacul. Bate ouăle cu furculița, cu sare și piper, până sunt omogene (nu spumă).", "Încinge tigaia la foc mediu cu uleiul de măsline și călește ciupercile și ceapa verde 3 min, întinse, nu îngrămădite — ciupercile trebuie să lase apa și să prindă culoare.", "Adaugă roșiile și spanacul, 1 min, cât să cadă spanacul. Dacă legumele au lăsat zeamă, las-o să scadă — altfel omleta iese apoasă.", "Dă focul mic, toarnă ouăle peste legume și amestecă lent cu spatula, trăgând marginile spre centru, 2–3 min, până se leagă dar rămâne cremoasă la mijloc.", "Oprește focul cu 30 de secunde mai devreme: omleta se termină singură în tigaia fierbinte.", "Prăjește pâinea uscat (fără unt). Brânza de vaci alături, cu mărar sau boia, sare și piper. Banana la final."], "sfat": "Ouăle la foc mic rămân moi; la foc mare proteina se strânge, elimină apa și omleta devine cauciucată. Vitamina C din roșii și ardei ajută absorbția fierului din gălbenuș. Brânza stă alături, nu în omletă — lactatele merg cu ouă, dar niciodată cu carne sau pește (regula casei).", "varianta": "Legumele = ce e în casă (ardei, dovlecel, praz). Banana ↔ măr / 150 g fructe de pădure.", "total": {"k": 1360, "p": 95, "g": 57, "c": 125, "f": 18}, "vit": [{"n": "A", "v": "1312", "u": "µg"}, {"n": "C", "v": "75", "u": "mg"}, {"n": "D", "v": "7.9", "u": "µg"}, {"n": "E", "v": "11.5", "u": "mg"}, {"n": "K", "v": "591", "u": "µg"}, {"n": "B6", "v": "2.3", "u": "mg"}, {"n": "Folat", "v": "543", "u": "µg"}, {"n": "B12", "v": "4.5", "u": "µg"}], "vitPartial": 0, "zile": ["Lu1", "Vi1", "Ma2", "Sâ2"]}, {"id": "MD2", "nume": "Ovăz peste noapte cu skyr, fructe de pădure, chia și nuci", "scurt": "Ovăz peste noapte", "grup": "Mic dejun", "masa": "mic dejun", "timp": "5′ (seara)", "tine": "3 zile", "kcal": {"s": 550, "m": 625}, "macro": {"s": {"p": 36, "g": 16, "c": 70, "f": 14}, "m": {"p": 38, "g": 20, "c": 77, "f": 15}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Skyr", "s": "200 g", "m": "200 g", "sm": "400 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Fulgi de ovăz", "s": "60 g", "m": "70 g", "sm": "130 g"}]}, {"eticheta": "Fruct", "items": [{"nume": "Fructe de pădure", "s": "100 g", "m": "100 g", "sm": "200 g"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Chia", "s": "10 g", "m": "10 g", "sm": "20 g"}, {"nume": "Nuci", "s": "10 g", "m": "15 g", "sm": "25 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Lapte 1,5%", "s": "100 ml", "m": "100 ml", "sm": "200 ml"}]}], "pasi": ["Seara, într-un borcan de 500 ml: fulgii de ovăz, chia, skyr-ul și laptele. Amestecă bine, până nu mai rămâne ovăz uscat pe fund.", "Adaugă fructele de pădure (merg direct congelate — se dezgheață peste noapte) și un vârf de scorțișoară. Amestecă scurt.", "Închide borcanul și ține-l la frigider minimum 6 ore. Chia se umflă și leagă compoziția ca un budincă.", "Dimineața presară nucile tocate grosier, chiar înainte de a mânca. Dacă e prea gros, subțiază cu 1–2 linguri de lapte."], "sfat": "Nucile se pun la final ca să rămână crocante și ca grăsimile lor să nu se oxideze peste noapte. Ovăzul ținut la rece formează amidon rezistent — hrană pentru bacteriile din colon și o creștere mai lină a glicemiei decât la ovăzul fiert. Se face pentru 2–3 zile deodată.", "varianta": "Iarna: ovăz fiert în lapte, skyr adăugat la final.", "total": {"k": 1175, "p": 73, "g": 36, "c": 147, "f": 29}, "vit": [{"n": "A", "v": "4.25", "u": "µg"}, {"n": "C", "v": "0.65", "u": "mg"}, {"n": "D", "v": "0", "u": "µg"}, {"n": "E", "v": "0.86", "u": "mg"}, {"n": "K", "v": "3.28", "u": "µg"}, {"n": "B6", "v": "0.52", "u": "mg"}, {"n": "Folat", "v": "104", "u": "µg"}, {"n": "B12", "v": "3", "u": "µg"}], "vitPartial": 4, "zile": ["Ma1", "Sâ1", "Mi2", "Du2"]}, {"id": "MD3", "nume": "Bol de iaurt grec cu banană, unt de arahide, ovăz și in", "scurt": "Bol de iaurt grec", "grup": "Mic dejun", "masa": "mic dejun", "timp": "5′", "tine": "nu", "kcal": {"s": 575, "m": 645}, "macro": {"s": {"p": 32, "g": 19, "c": 76, "f": 12}, "m": {"p": 35, "g": 22, "c": 84, "f": 13}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Iaurt grec", "s": "200 g", "m": "200 g", "sm": "400 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Fulgi de ovăz", "s": "40 g", "m": "50 g", "sm": "90 g"}]}, {"eticheta": "Fruct", "items": [{"nume": "Banană", "s": "1 buc.", "m": "1 buc.", "sm": "2 buc."}, {"nume": "Afine", "s": "50 g", "m": "50 g", "sm": "100 g"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Unt de arahide", "s": "15 g", "m": "20 g", "sm": "35 g"}, {"nume": "In măcinat", "s": "10 g", "m": "10 g", "sm": "20 g"}]}], "pasi": ["Pune iaurtul grec în bol și întinde-l ușor cu dosul lingurii.", "Taie banana felii și așaz-o cu afinele pe jumătate din suprafață.", "Presară fulgii de ovăz și inul măcinat pe cealaltă jumătate. Inul trebuie măcinat — sămânța întreagă trece nedigerată.", "Picură untul de arahide deasupra; dacă e prea tare, amestecă-l întâi cu o lingură de apă caldă, ca să curgă. Pudrează cu scorțișoară."], "sfat": "Inul măcinat pe loc (10 secunde în râșnița de cafea) își păstrează omega-3; măcinat din comerț se oxidează în câteva săptămâni. Untul de arahide: doar cel cu 100% arahide, fără zahăr și fără ulei de palmier. Banana mai coaptă înseamnă mai dulce, fără să adaugi nimic.", "varianta": "", "total": {"k": 1220, "p": 67, "g": 41, "c": 159, "f": 25}, "vit": [{"n": "A", "v": "370", "u": "µg"}, {"n": "C", "v": "33.9", "u": "mg"}, {"n": "D", "v": "0", "u": "µg"}, {"n": "E", "v": "4.59", "u": "mg"}, {"n": "K", "v": "24.1", "u": "µg"}, {"n": "B6", "v": "1.49", "u": "mg"}, {"n": "Folat", "v": "179", "u": "µg"}, {"n": "B12", "v": "2.08", "u": "µg"}], "vitPartial": 0, "zile": ["Jo1", "Lu2", "Vi2"]}, {"id": "MD4", "nume": "Ouă ochiuri cu avocado pe pâine, roșii, castravete, brânză de vaci + măr", "scurt": "Ochiuri cu avocado", "grup": "Mic dejun", "masa": "mic dejun 🥚", "timp": "10′", "tine": "nu", "kcal": {"s": 655, "m": 750}, "macro": {"s": {"p": 41, "g": 28, "c": 65, "f": 13}, "m": {"p": 50, "g": 34, "c": 66, "f": 13}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Ouă", "s": "3 buc.", "m": "4 buc.", "sm": "7 buc."}, {"nume": "Brânză de vaci", "s": "100 g", "m": "120 g", "sm": "220 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Roșii", "s": "100 g", "m": "100 g", "sm": "200 g"}, {"nume": "Castravete", "s": "100 g", "m": "100 g", "sm": "200 g"}, {"nume": "Rucola", "s": "20 g", "m": "20 g", "sm": "40 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Pâine integrală", "s": "50 g", "m": "50 g", "sm": "100 g"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Avocado", "s": "50 g", "m": "50 g", "sm": "100 g"}]}, {"eticheta": "Fruct", "items": [{"nume": "Măr", "s": "1 buc.", "m": "1 buc.", "sm": "2 buc."}]}], "pasi": ["Prăjește feliile de pâine uscat, în tigaie sau prăjitor, până sunt crocante — așa suportă avocado fără să se înmoaie.", "Zdrobește avocado cu furculița, cu suc de lămâie, sare și piper. Lămâia nu e doar pentru gust: ține avocado verde.", "Ouăle: fie ochiuri în apă (apă la fiert mic, o lingură de oțet, oul spart întâi într-o cană și lăsat ușor în apă, 3 min), fie în tigaie la foc mic, cu capac, ca să nu se ardă marginile.", "Întinde avocado pe pâine, așază ouăle deasupra, sare și piper.", "Alături: rucola, roșiile felii, castravetele și brânza de vaci cu mărar. Un strop de lămâie peste salată."], "sfat": "Gălbenușul lăsat moale păstrează mai bine colina și vitaminele A, D și E, care se degradează la gătire lungă. Grăsimea din avocado ajută la absorbția vitaminelor liposolubile din gălbenuș și a carotenoizilor din roșii și rucola.", "varianta": "", "total": {"k": 1405, "p": 91, "g": 61, "c": 131, "f": 25}, "vit": [{"n": "A", "v": "925", "u": "µg"}, {"n": "C", "v": "65.6", "u": "mg"}, {"n": "D", "v": "7.7", "u": "µg"}, {"n": "E", "v": "10.9", "u": "mg"}, {"n": "K", "v": "130", "u": "µg"}, {"n": "B6", "v": "1.67", "u": "mg"}, {"n": "Folat", "v": "415", "u": "µg"}, {"n": "B12", "v": "4.46", "u": "µg"}], "vitPartial": 0, "zile": ["Mi1", "Du1", "Jo2"]}, {"id": "G1", "nume": "Skyr cu măr și migdale", "scurt": "Skyr cu măr", "grup": "Gustări", "masa": "gustare", "timp": "2′", "tine": "—", "kcal": {"s": 300, "m": 355}, "macro": {"s": {"p": 24, "g": 9, "c": 35, "f": 6}, "m": {"p": 30, "g": 11, "c": 38, "f": 7}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Skyr", "s": "200 g", "m": "250 g", "sm": "450 g"}]}, {"eticheta": "Fruct", "items": [{"nume": "Măr", "s": "1 buc.", "m": "1 buc.", "sm": "2 buc."}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Migdale", "s": "15 g", "m": "20 g", "sm": "35 g"}]}], "pasi": ["Pune skyr-ul în bol.", "Taie mărul cubulețe, cu coajă cu tot — acolo sunt fibrele și polifenolii. Presară scorțișoară peste el.", "Adaugă migdalele, întregi sau tocate grosier, alături sau deasupra."], "sfat": "Proteina din skyr plus fibra din măr țin de foame ~3 ore — exact ce trebuie la 16:00, ca să nu ajungi flămând la cină. Migdalele întregi se mestecă mai mult și se digeră mai lent decât cele măcinate; ~15 g ajung, sunt dense caloric.", "varianta": "", "total": {"k": 655, "p": 54, "g": 20, "c": 73, "f": 13}, "vit": [{"n": "A", "v": "15.3", "u": "µg"}, {"n": "C", "v": "16.6", "u": "mg"}, {"n": "D", "v": "0", "u": "µg"}, {"n": "E", "v": "9.66", "u": "mg"}, {"n": "K", "v": "7.92", "u": "µg"}, {"n": "B6", "v": "0.48", "u": "mg"}, {"n": "Folat", "v": "57.7", "u": "µg"}, {"n": "B12", "v": "3.38", "u": "µg"}], "vitPartial": 0, "zile": ["Lu1", "Vi1", "Du1", "Mi2", "Sâ2"]}, {"id": "G2", "nume": "Brânză de vaci cu pâine integrală și legume crude", "scurt": "Brânză de vaci cu pâine", "grup": "Gustări", "masa": "gustare", "timp": "5′", "tine": "—", "kcal": {"s": 265, "m": 330}, "macro": {"s": {"p": 22, "g": 5, "c": 34, "f": 5}, "m": {"p": 29, "g": 7, "c": 41, "f": 6}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Brânză de vaci", "s": "150 g", "m": "200 g", "sm": "350 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Pâine integrală", "s": "40 g", "m": "50 g", "sm": "90 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Castravete", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Ardei", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Morcov", "s": "50 g", "m": "50 g", "sm": "100 g"}]}], "pasi": ["Amestecă brânza de vaci cu sare, piper și mărar tocat (sau boia afumată, dacă vrei alt gust).", "Întinde-o pe feliile de pâine integrală.", "Taie castravetele, ardeiul și morcovul bețe și pune-le alături — se mănâncă crude, cu mâna."], "sfat": "Brânza de vaci e în cea mai mare parte cazeină, proteină cu digestie lentă: gustarea ține până la cină. Legumele tăiate bețe se mănâncă în cantitate mai mare decât aceleași legume tocate în salată — e o diferență reală de câteva sute de grame pe săptămână.", "varianta": "Ridichi lângă castravete — doar la cine le vrea.", "total": {"k": 590, "p": 51, "g": 12, "c": 74, "f": 11}, "vit": [{"n": "A", "v": "1235", "u": "µg"}, {"n": "C", "v": "136", "u": "mg"}, {"n": "D", "v": "0", "u": "µg"}, {"n": "E", "v": "4.94", "u": "mg"}, {"n": "K", "v": "41.5", "u": "µg"}, {"n": "B6", "v": "0.86", "u": "mg"}, {"n": "Folat", "v": "138", "u": "µg"}, {"n": "B12", "v": "1.65", "u": "µg"}], "vitPartial": 0, "zile": ["Mi1", "Sâ1", "Lu2", "Vi2", "Du2"]}, {"id": "G3", "nume": "Shake post-sală: lapte, skyr, banană, unt de arahide", "scurt": "Shake post-sală", "grup": "Gustări", "masa": "gustare 🏋️", "timp": "3′", "tine": "—", "kcal": {"s": 345, "m": 405}, "macro": {"s": {"p": 25, "g": 9, "c": 45, "f": 4}, "m": {"p": 32, "g": 12, "c": 48, "f": 4}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Skyr", "s": "150 g", "m": "200 g", "sm": "350 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Lapte 1,5%", "s": "200 ml", "m": "200 ml", "sm": "400 ml"}]}, {"eticheta": "Fruct", "items": [{"nume": "Banană", "s": "1 buc.", "m": "1 buc.", "sm": "2 buc."}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Unt de arahide", "s": "10 g", "m": "15 g", "sm": "25 g"}]}], "pasi": ["Pune în blender laptele, skyr-ul, banana și untul de arahide.", "Blender 30–40 de secunde, până e omogen. Cacao neîndulcită sau scorțișoară, opțional.", "Bea-l în prima oră după antrenament.", "Fără blender: skyr-ul cu banana tăiată mărunt și zdrobită cu furculița, iar laptele băut alături."], "sfat": "După antrenamentul de forță contează combinația proteină + carbohidrați: skyr-ul și laptele dau ~30 g proteine bogate în leucină, banana reface glicogenul. Untul de arahide rămâne la 10–15 g — grăsimea încetinește golirea stomacului, adică exact opusul a ce vrei acum.", "varianta": "De ce: proteină rapidă + carbohidrați simpli după forță.", "total": {"k": 755, "p": 57, "g": 21, "c": 92, "f": 7}, "vit": [{"n": "A", "v": "10.7", "u": "µg"}, {"n": "C", "v": "20.9", "u": "mg"}, {"n": "D", "v": "0", "u": "µg"}, {"n": "E", "v": "2.55", "u": "mg"}, {"n": "K", "v": "1.27", "u": "µg"}, {"n": "B6", "v": "1.21", "u": "mg"}, {"n": "Folat", "v": "94.2", "u": "µg"}, {"n": "B12", "v": "2.62", "u": "µg"}], "vitPartial": 2, "zile": ["Ma1", "Jo1", "Ma2", "Jo2"]}, {"id": "P1", "nume": "Pui la cuptor cu legume la tavă, cartof dulce și sos de tahini cu lămâie", "scurt": "Pui la cuptor cu legume la tavă", "grup": "Feluri principale", "masa": "prânz/cină", "timp": "45′ (10 activ)", "tine": "3 zile", "kcal": {"s": 585, "m": 670}, "macro": {"s": {"p": 44, "g": 18, "c": 65, "f": 14}, "m": {"p": 53, "g": 21, "c": 69, "f": 14}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Piept de pui", "s": "150 g", "m": "190 g", "sm": "340 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Broccoli", "s": "100 g", "m": "100 g", "sm": "200 g"}, {"nume": "Morcov", "s": "60 g", "m": "60 g", "sm": "120 g"}, {"nume": "Ceapă", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Ardei", "s": "60 g", "m": "60 g", "sm": "120 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Cartof dulce", "s": "200 g", "m": "220 g", "sm": "420 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Tahini", "s": "12 g", "m": "12 g", "sm": "24 g"}, {"nume": "Usturoi", "s": "3 g", "m": "3 g", "sm": "6 g"}, {"nume": "Suc de lămâie", "s": "10 ml", "m": "10 ml", "sm": "20 ml"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Ulei de măsline", "s": "7 g", "m": "9 g", "sm": "16 g"}]}], "pasi": ["Încinge cuptorul la 200 °C. Taie cartoful dulce cuburi de 2 cm și morcovul rondele groase; amestecă-le într-un bol cu jumătate din ulei, boia afumată, sare și piper.", "Întinde-le pe tavă cu hârtie de copt, într-un singur strat, fără să se atingă — înghesuite se aburesc în loc să se rumenească. 20 min.", "Între timp condimentează pieptul de pui cu oregano, usturoi pisat, coajă și suc de lămâie, sare și piper. Taie broccoli buchețele, ceapa felii groase, ardeiul fâșii și amestecă-le cu restul de ulei.", "Scoate tava, împinge cartofii într-o parte, adaugă puiul și legumele verzi. Încă 20–25 min, până puiul ajunge la 74 °C la mijloc (sau până zeama iese limpede).", "Sosul: amestecă tahini cu sucul de lămâie și usturoiul pisat — se va strânge și se va face pastă. Adaugă 2 linguri de apă rece, lingură cu lingură, bătând cu furculița, până devine cremos ca o smântână. Sare.", "Lasă puiul 5 min înainte să-l tai. Sosul se toarnă în farfurie, nu la cuptor."], "sfat": "Broccoli intră în a doua parte a coacerii ca să nu-și piardă culoarea și sulforafanul. Puiul scos la 74 °C rămâne suculent — peste, se usucă și devine făinos. Sosul de tahini ține locul celui de iaurt la masa cu carne (regula casei) și aduce calciu, magneziu și seleniu.", "varianta": "", "total": {"k": 1255, "p": 97, "g": 40, "c": 134, "f": 28}, "vit": [{"n": "A", "v": "4262", "u": "µg"}, {"n": "C", "v": "366", "u": "mg"}, {"n": "D", "v": "0", "u": "µg"}, {"n": "E", "v": "9.65", "u": "mg"}, {"n": "K", "v": "243", "u": "µg"}, {"n": "B6", "v": "4.74", "u": "mg"}, {"n": "Folat", "v": "328", "u": "µg"}, {"n": "B12", "v": "0.71", "u": "µg"}], "vitPartial": 0, "zile": ["Lu1", "Ma1", "Vi2", "Sâ2"]}, {"id": "P2", "nume": "Tocăniță de vită cu ciuperci, mămăligă și salată de varză roșie cu mere", "scurt": "Tocăniță de vită cu mămăligă", "grup": "Feluri principale", "masa": "prânz/cină", "timp": "75′ (15 activ)", "tine": "4 zile · congelator", "kcal": {"s": 670, "m": 755}, "macro": {"s": {"p": 50, "g": 18, "c": 85, "f": 14}, "m": {"p": 59, "g": 21, "c": 89, "f": 14}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Vită slabă", "s": "160 g", "m": "200 g", "sm": "360 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Ciuperci", "s": "80 g", "m": "80 g", "sm": "160 g"}, {"nume": "Ceapă", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Morcov", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Ardei", "s": "40 g", "m": "40 g", "sm": "80 g"}, {"nume": "Varză", "s": "100 g", "m": "100 g", "sm": "200 g"}, {"nume": "Măr", "s": "40 g", "m": "40 g", "sm": "80 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Mălai", "s": "65 g", "m": "70 g", "sm": "135 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Roșii pasate", "s": "100 g", "m": "100 g", "sm": "200 g"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Ulei de măsline", "s": "10 g", "m": "12 g", "sm": "22 g"}]}], "pasi": ["Taie vita cuburi de 3 cm și usuc-o cu un șervet: carnea udă nu se rumenește, fierbe. Sare și piper.", "Încinge bine oala cu jumătate din ulei și rumenește carnea în două tranșe, 2–3 min pe parte, fără s-o înghesui. Scoate-o deoparte.", "În aceeași oală: ceapa și morcovul 5 min, apoi ciupercile și ardeiul, până ciupercile lasă apa și se rumenesc. Dezlipește cu lingura de lemn tot ce s-a prins pe fund — acolo e gustul.", "Pune carnea înapoi cu roșiile pasate, boiaua, cimbrul, foaia de dafin și apă cât să acopere. Foc mic, cu capac, 60 min (25 min la oala sub presiune), până carnea se desface cu furculița.", "Mămăliga se face proaspăt, la final: apă cu sare la fiert, mălaiul în ploaie, amestecat continuu, 10 min la foc mic.", "Salata: varza roșie tăiată foarte fin și frecată cu sare și oțet 2 min (se înmoaie și își aprinde culoarea), mărul julienne, restul de ulei."], "sfat": "Fără telemea sau smântână peste mămăligă — e masă cu carne (regula casei). Fierberea lungă la foc mic transformă colagenul din vită în gelatină: de acolo vine textura, nu din grăsime. Varza roșie crudă cu măr adaugă fibre, vitamina C și antociani lângă un fel gătit mult.", "varianta": "Fără telemea peste mămăligă — regula: nu amestecăm lactate cu carne.", "total": {"k": 1425, "p": 109, "g": 39, "c": 173, "f": 28}, "vit": [{"n": "A", "v": "1047", "u": "µg"}, {"n": "C", "v": "217", "u": "mg"}, {"n": "D", "v": "0.32", "u": "µg"}, {"n": "E", "v": "10.9", "u": "mg"}, {"n": "K", "v": "197", "u": "µg"}, {"n": "B6", "v": "3.92", "u": "mg"}, {"n": "Folat", "v": "261", "u": "µg"}, {"n": "B12", "v": "6.69", "u": "µg"}], "vitPartial": 0, "zile": ["Mi1", "Jo1"]}, {"id": "P3", "nume": "Doradă la cuptor cu fasole verde cu usturoi, salată de rucola, quinoa și sos de lămâie cu mărar 🐟", "scurt": "Doradă cu quinoa", "grup": "Feluri principale", "masa": "cină", "timp": "25′", "tine": "1 zi (rece)", "kcal": {"s": 585, "m": 640}, "macro": {"s": {"p": 49, "g": 20, "c": 53, "f": 10}, "m": {"p": 57, "g": 21, "c": 56, "f": 10}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Doradă", "s": "200 g", "m": "240 g", "sm": "440 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Fasole verde", "s": "150 g", "m": "150 g", "sm": "300 g"}, {"nume": "Rucola", "s": "40 g", "m": "40 g", "sm": "80 g"}, {"nume": "Roșii", "s": "80 g", "m": "80 g", "sm": "160 g"}, {"nume": "Usturoi", "s": "3 g", "m": "3 g", "sm": "6 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Quinoa", "s": "55 g", "m": "60 g", "sm": "115 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Suc de lămâie", "s": "10 ml", "m": "10 ml", "sm": "20 ml"}, {"nume": "Usturoi", "s": "2 g", "m": "2 g", "sm": "4 g"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Ulei de măsline", "s": "12 g", "m": "12 g", "sm": "24 g"}]}], "pasi": ["Cuptorul la 200 °C. Clătește quinoa în sită sub apă rece 30 de secunde (scapi de saponine, gustul amărui), apoi fierbe-o 15 min în dublu volum de apă cu sare, cu capac. La final las-o 5 min deoparte și afâneaz-o cu furculița.", "Usucă dorada cu un șervet, crestează pielea de 2–3 ori, sare și piper pe dinăuntru și pe dinafară, felii de lămâie și usturoi în burtă, jumătate din ulei deasupra.", "Coace 18–20 min la 200 °C (file: 12–14 min). E gata când carnea e opacă și se desprinde de os.", "Fasolea verde: 5 min în apă clocotită cu sare, scursă, apoi 1 min în tigaie cu usturoi feliat și un strop de ulei.", "Salata: rucola cu roșiile tăiate în două și un strop de lămâie.", "Sosul: suc de lămâie, restul de ulei, mărar tocat și usturoi pisat, bătute cu furculița; se toarnă peste pește la servire."], "sfat": "Peștele se coace, nu se prăjește: omega-3 se degradează la temperaturi mari și timp lung. Se gătește proaspăt, în ziua aceea — peștele reîncălzit își pierde textura și capătă miros. Lângă pește nu punem lactate (regula casei), de aceea sosul e pe bază de lămâie și ulei.", "varianta": "Se face ×2, proaspăt. Cântărită ca file (la pește întreg, ~½ din greutate e carne). Merge la fel cu chefal, păstrăv sau — mai rar — somon (+150 kcal).", "total": {"k": 1225, "p": 107, "g": 41, "c": 109, "f": 20}, "vit": [{"n": "A", "v": "471", "u": "µg"}, {"n": "C", "v": "81.4", "u": "mg"}, {"n": "D", "v": "24.6", "u": "µg"}, {"n": "E", "v": "12.4", "u": "mg"}, {"n": "K", "v": "244", "u": "µg"}, {"n": "B6", "v": "3.06", "u": "mg"}, {"n": "Folat", "v": "438", "u": "µg"}, {"n": "B12", "v": "1.32", "u": "µg"}], "vitPartial": 0, "zile": ["Ma1"]}, {"id": "P4", "nume": "Salată de ton cu năut, legume crude și vinegretă de muștar 🐟", "scurt": "Salată de ton", "grup": "Feluri principale", "masa": "prânz", "timp": "10′ (fără gătit)", "tine": "2 zile", "kcal": {"s": 605, "m": 680}, "macro": {"s": {"p": 47, "g": 19, "c": 65, "f": 16}, "m": {"p": 57, "g": 20, "c": 72, "f": 18}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Ton (conservă, scurs)", "s": "110 g", "m": "140 g", "sm": "250 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Castravete", "s": "70 g", "m": "70 g", "sm": "140 g"}, {"nume": "Ardei", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Roșii", "s": "80 g", "m": "80 g", "sm": "160 g"}, {"nume": "Salată verde", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Ceapă", "s": "20 g", "m": "20 g", "sm": "40 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Năut", "s": "150 g", "m": "180 g", "sm": "330 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Muștar", "s": "8 g", "m": "8 g", "sm": "16 g"}, {"nume": "Suc de lămâie", "s": "10 ml", "m": "10 ml", "sm": "20 ml"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Ulei de măsline", "s": "10 g", "m": "10 g", "sm": "20 g"}, {"nume": "Măsline", "s": "15 g", "m": "15 g", "sm": "30 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Pâine integrală", "s": "40 g", "m": "40 g", "sm": "80 g"}]}], "pasi": ["Scurge bine tonul (apasă capacul conservei) și năutul; clătește năutul sub apă rece, ca să scapi de lichidul de conservare.", "Taie castravetele, ardeiul și roșiile cuburi, ceapa foarte fin — dacă e iute, ține-o 5 min în apă rece cu oțet. Salata verde se rupe cu mâna, nu se taie.", "Vinegreta: muștar, suc de lămâie, ulei de măsline și mărar, bătute cu furculița până se leagă. Sare, piper.", "Amestecă legumele cu năutul și dressingul, apoi pune tonul deasupra, rupt cu furculița — nu amestecat, ca să rămână bucăți. Măslinele felii.", "Pâinea integrală alături. Dacă o pregătești pentru a doua zi, ține dressingul separat și pune-l la masă."], "sfat": "Năutul aduce fibrele și amidonul care lipsesc din ton: împreună ies o masă completă, fără gătit. Tonul e pește slab — omega-3 vine de la doradă și păstrăv, la cinele de marți. Se ține 2 zile la frigider, dar salata verde se adaugă la servire.", "varianta": "Ridichi — doar la cine le vrea. Săpt. 2: 60 g linte uscată fiartă în loc de năut. Tonul e pește slab — omega-3 vine de la doradă / păstrăv / chefal, la cinele de marți.", "total": {"k": 1285, "p": 103, "g": 39, "c": 136, "f": 34}, "vit": [{"n": "A", "v": "610", "u": "µg"}, {"n": "C", "v": "174", "u": "mg"}, {"n": "D", "v": "0", "u": "µg"}, {"n": "E", "v": "9.25", "u": "mg"}, {"n": "K", "v": "197", "u": "µg"}, {"n": "B6", "v": "2.07", "u": "mg"}, {"n": "Folat", "v": "333", "u": "µg"}, {"n": "B12", "v": "7.47", "u": "µg"}], "vitPartial": 0, "zile": ["Mi1", "Mi2"]}, {"id": "P5", "nume": "Chili de linte cu pui tocat, avocado și salată de castraveți", "scurt": "Chili de linte cu pui", "grup": "Feluri principale", "masa": "prânz/cină", "timp": "45′ (10 activ)", "tine": "4 zile · congelator", "kcal": {"s": 660, "m": 755}, "macro": {"s": {"p": 56, "g": 18, "c": 76, "f": 17}, "m": {"p": 67, "g": 20, "c": 82, "f": 18}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Piept de pui tocat", "s": "150 g", "m": "190 g", "sm": "340 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Ceapă", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Ardei", "s": "60 g", "m": "60 g", "sm": "120 g"}, {"nume": "Morcov", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Castravete", "s": "100 g", "m": "100 g", "sm": "200 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Linte", "s": "65 g", "m": "75 g", "sm": "140 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Roșii pasate", "s": "150 g", "m": "150 g", "sm": "300 g"}, {"nume": "Suc de lămâie", "s": "5 ml", "m": "5 ml", "sm": "10 ml"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Ulei de măsline", "s": "5 g", "m": "6 g", "sm": "11 g"}, {"nume": "Avocado", "s": "50 g", "m": "50 g", "sm": "100 g"}]}], "pasi": ["Încinge oala cu uleiul și rumenește puiul tocat, desfăcându-l cu lingura, până nu mai e roz și prinde puțină culoare.", "Adaugă ceapa, ardeiul și morcovul tocate mărunt; 5 min, până se înmoaie.", "Pune chimionul, boiaua afumată, oregano, usturoiul și chili și prăjește-le 30–60 de secunde în grăsime — așa își eliberează aromele; puse direct în apă rămân fade.", "Adaugă lintea clătită, roșiile pasate și apă cu două degete peste. Foc mic, capac întredeschis, 30–35 min, până lintea e moale dar întreagă.", "Sarea se pune la final: pusă devreme, întărește coaja lintei.", "Salata: castravete felii cu suc de lămâie, mărar și sare. Avocado cuburi se pune peste chili în farfurie, la servire — nu se fierbe și nu se congelează."], "sfat": "Se face ×8 și jumătate merge la congelator: chili-ul se congelează perfect și e mai bun a doua zi. Lintea cu puiul dau ~10 g de fibre pe porție și o proteină completă. Avocado adaugă grăsimi bune și taie din picant — de aceea intră crud, la sfârșit.", "varianta": "Se face ×8 — jumătate la congelator. Piept de pui tocat acasă sau la măcelar; pui tocat comercial: +35 kcal, −8 g P.", "total": {"k": 1415, "p": 123, "g": 38, "c": 158, "f": 35}, "vit": [{"n": "A", "v": "1152", "u": "µg"}, {"n": "C", "v": "224", "u": "mg"}, {"n": "D", "v": "0", "u": "µg"}, {"n": "E", "v": "14.8", "u": "mg"}, {"n": "K", "v": "97.1", "u": "µg"}, {"n": "B6", "v": "4.84", "u": "mg"}, {"n": "Folat", "v": "924", "u": "µg"}, {"n": "B12", "v": "0.71", "u": "µg"}], "vitPartial": 0, "zile": ["Lu1", "Jo2", "Vi2"]}, {"id": "P6", "nume": "Paste integrale cu pui, sos de roșii cu dovlecel și salată de rucola cu roșii cherry", "scurt": "Paste cu pui și dovlecel", "grup": "Feluri principale", "masa": "prânz/cină", "timp": "30′", "tine": "3 zile", "kcal": {"s": 635, "m": 710}, "macro": {"s": {"p": 50, "g": 17, "c": 79, "f": 13}, "m": {"p": 60, "g": 19, "c": 82, "f": 14}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Piept de pui", "s": "150 g", "m": "190 g", "sm": "340 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Dovlecel", "s": "150 g", "m": "150 g", "sm": "300 g"}, {"nume": "Ceapă", "s": "40 g", "m": "40 g", "sm": "80 g"}, {"nume": "Rucola", "s": "40 g", "m": "40 g", "sm": "80 g"}, {"nume": "Roșii", "s": "80 g", "m": "80 g", "sm": "160 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Paste integrale", "s": "70 g", "m": "75 g", "sm": "145 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Roșii pasate", "s": "150 g", "m": "150 g", "sm": "300 g"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Ulei de măsline", "s": "8 g", "m": "9 g", "sm": "17 g"}, {"nume": "Măsline", "s": "15 g", "m": "15 g", "sm": "30 g"}]}], "pasi": ["Pune apa pentru paste la fiert, sărată ca marea.", "Taie puiul fâșii, condimentează-l și rumenește-l 3–4 min în tigaie încinsă cu jumătate din ulei, în strat subțire. Scoate-l — ținut tot timpul în sos, se usucă.", "În aceeași tigaie: ceapa și dovlecelul cuburi, 5 min. Adaugă roșiile pasate, usturoiul, busuiocul și oregano și fierbe 10 min la foc mic, până sosul se leagă.", "Fierbe pastele al dente — un minut mai puțin decât scrie pe pachet — și păstrează o cană din apa lor.", "Pune puiul înapoi în sos, adaugă pastele scurse și 2–3 linguri din apa de la paste; amestecă 1 min pe foc, cât amidonul leagă sosul de paste. Măslinele felii deasupra.", "Alături: rucola cu roșii cherry, un strop de lămâie și restul de ulei."], "sfat": "Pastele al dente au indice glicemic mai mic decât cele răsfierte; integrale, au de 3–4 ori mai multe fibre decât cele albe. Fără parmezan — e masă cu carne (regula casei); gustul îl dau busuiocul, usturoiul și măslinele.", "varianta": "", "total": {"k": 1350, "p": 110, "g": 36, "c": 161, "f": 27}, "vit": [{"n": "A", "v": "306", "u": "µg"}, {"n": "C", "v": "126", "u": "mg"}, {"n": "D", "v": "0", "u": "µg"}, {"n": "E", "v": "13", "u": "mg"}, {"n": "K", "v": "136", "u": "µg"}, {"n": "B6", "v": "4.32", "u": "mg"}, {"n": "Folat", "v": "352", "u": "µg"}, {"n": "B12", "v": "0.71", "u": "µg"}], "vitPartial": 0, "zile": ["Jo1", "Vi1", "Sâ2", "Du2"]}, {"id": "P7", "nume": "Cotlet de porc cu piure de conopidă și morcov, cartofi copți și salată de varză", "scurt": "Cotlet de porc cu piure de conopidă", "grup": "Feluri principale", "masa": "prânz/cină", "timp": "40′", "tine": "3 zile (salata proaspăt)", "kcal": {"s": 525, "m": 615}, "macro": {"s": {"p": 43, "g": 16, "c": 54, "f": 12}, "m": {"p": 52, "g": 20, "c": 59, "f": 13}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Cotlet de porc", "s": "150 g", "m": "190 g", "sm": "340 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Conopidă", "s": "150 g", "m": "150 g", "sm": "300 g"}, {"nume": "Morcov", "s": "80 g", "m": "80 g", "sm": "160 g"}, {"nume": "Varză", "s": "120 g", "m": "120 g", "sm": "240 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Cartofi", "s": "180 g", "m": "210 g", "sm": "390 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Muștar", "s": "8 g", "m": "8 g", "sm": "16 g"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Ulei de măsline", "s": "10 g", "m": "12 g", "sm": "22 g"}]}], "pasi": ["Cuptorul la 200 °C. Cartofii feliați de 1 cm, amestecați cu jumătate din ulei, rozmarin și sare, pe tavă într-un singur strat, 25 min, întorși o dată la mijloc.", "Fierbe conopida și morcovul 15 min în apă cu puțină sare, până se străpung ușor cu furculița. Scurge-le, dar păstrează puțină apă de la fiert.", "Pasează-le cu restul de ulei, usturoi, un vârf de nucșoară, sare și 2–3 linguri din apa de la fiert, până iese un piure cremos. Fără lapte sau unt — e masă cu carne.", "Bate cotletul până are grosime uniformă de ~1,5 cm și condimentează-l cu sare, piper și cimbru.", "Tigaia foarte bine încinsă: 3–4 min pe fiecare parte, fără să miști carnea în primul minut, ca să se formeze crusta. Apoi las-o 5 min pe un fund de lemn, înainte de tăiere.", "Salata: varza tăiată fin, frecată cu sare 1 min, apoi oțet, chimen și puțin ulei. Muștarul se pune peste cotlet, la servire."], "sfat": "Piureul de conopidă cu morcov are cam o treime din caloriile unuia de cartofi și de câteva ori mai multe fibre — de aceea cartofii rămân puțini și copți, nu pasați. Carnea odihnită 5 min își ține zeama înăuntru; tăiată imediat, o lasă pe tocător.", "varianta": "Piureul merge și cu broccoli în loc de morcov.", "total": {"k": 1135, "p": 95, "g": 36, "c": 113, "f": 25}, "vit": [{"n": "A", "v": "1349", "u": "µg"}, {"n": "C", "v": "319", "u": "mg"}, {"n": "D", "v": "1.02", "u": "µg"}, {"n": "E", "v": "5.35", "u": "mg"}, {"n": "K", "v": "271", "u": "µg"}, {"n": "B6", "v": "4.81", "u": "mg"}, {"n": "Folat", "v": "364", "u": "µg"}, {"n": "B12", "v": "1.73", "u": "µg"}], "vitPartial": 0, "zile": ["Vi1", "Sâ1"]}, {"id": "P8", "nume": "Curry de pui cu conopidă, spanac și năut, orez basmati", "scurt": "Curry de pui cu năut", "grup": "Feluri principale", "masa": "prânz/cină", "timp": "35′", "tine": "3 zile", "kcal": {"s": 650, "m": 730}, "macro": {"s": {"p": 49, "g": 16, "c": 79, "f": 12}, "m": {"p": 59, "g": 18, "c": 83, "f": 12}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Piept de pui", "s": "150 g", "m": "190 g", "sm": "340 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Conopidă", "s": "120 g", "m": "120 g", "sm": "240 g"}, {"nume": "Spanac", "s": "80 g", "m": "80 g", "sm": "160 g"}, {"nume": "Ceapă", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Roșii", "s": "60 g", "m": "60 g", "sm": "120 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Orez basmati", "s": "55 g", "m": "60 g", "sm": "115 g"}, {"nume": "Năut", "s": "80 g", "m": "80 g", "sm": "160 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Lapte de cocos light", "s": "50 ml", "m": "60 ml", "sm": "110 ml"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Ulei de măsline", "s": "5 g", "m": "6 g", "sm": "11 g"}]}], "pasi": ["Pune orezul basmati la fiert: 1 parte orez la 1,5 apă, capac, 12 min, apoi încă 5 min deoparte, fără să ridici capacul.", "Călește ceapa tocată în ulei 3–4 min, apoi adaugă ghimbirul ras și usturoiul, 30 de secunde.", "Pune curry-ul, turmericul și chimionul și prăjește-le 1 min, până miros. Turmericul are nevoie de grăsime și de un praf de piper negru ca să fie absorbit.", "Adaugă puiul cubulețe, 5 min, doar cât se albește pe toate părțile.", "Toarnă roșiile, laptele de cocos și pune conopida buchețele și năutul scurs; fierbe 15 min la foc mic, fără capac, până conopida e moale și sosul se leagă.", "Spanacul la final, 2 min, doar cât cade. Coriandru proaspăt și un strop de lămâie deasupra."], "sfat": "Laptele de cocos light dă cremozitate cu o treime din grăsimile celui gras — de aceea sunt suficiente 50–60 g. Conopida și spanacul țin legumele la 40% din farfurie fără să crească caloriile, iar năutul completează orezul cu fibre și proteină vegetală.", "varianta": "", "total": {"k": 1385, "p": 108, "g": 34, "c": 162, "f": 23}, "vit": [{"n": "A", "v": "833", "u": "µg"}, {"n": "C", "v": "185", "u": "mg"}, {"n": "D", "v": "0", "u": "µg"}, {"n": "E", "v": "8.18", "u": "mg"}, {"n": "K", "v": "832", "u": "µg"}, {"n": "B6", "v": "4.1", "u": "mg"}, {"n": "Folat", "v": "601", "u": "µg"}, {"n": "B12", "v": "0.71", "u": "µg"}], "vitPartial": 2, "zile": ["Sâ1", "Du1"]}, {"id": "P10", "nume": "Chiftele de pui la cuptor cu salată grecească, orez brun și sos de tahini", "scurt": "Chiftele de pui cu orez brun", "grup": "Feluri principale", "masa": "prânz/cină", "timp": "45′", "tine": "3 zile (salata proaspăt)", "kcal": {"s": 670, "m": 745}, "macro": {"s": {"p": 45, "g": 24, "c": 71, "f": 8}, "m": {"p": 54, "g": 26, "c": 75, "f": 8}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Piept de pui", "s": "150 g", "m": "190 g", "sm": "340 g"}, {"nume": "Fulgi de ovăz", "s": "15 g", "m": "15 g", "sm": "30 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Roșii", "s": "100 g", "m": "100 g", "sm": "200 g"}, {"nume": "Castravete", "s": "100 g", "m": "100 g", "sm": "200 g"}, {"nume": "Ceapă", "s": "30 g", "m": "30 g", "sm": "60 g"}, {"nume": "Ardei", "s": "50 g", "m": "50 g", "sm": "100 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Orez brun", "s": "55 g", "m": "60 g", "sm": "115 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Tahini", "s": "12 g", "m": "12 g", "sm": "24 g"}, {"nume": "Suc de lămâie", "s": "10 ml", "m": "10 ml", "sm": "20 ml"}, {"nume": "Usturoi", "s": "3 g", "m": "3 g", "sm": "6 g"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Măsline", "s": "20 g", "m": "20 g", "sm": "40 g"}, {"nume": "Ulei de măsline", "s": "8 g", "m": "9 g", "sm": "17 g"}]}], "pasi": ["Pune orezul brun la fiert — 30 min, are nevoie de cel mai mult timp din toată rețeta.", "Cuptorul la 200 °C. Amestecă pieptul tocat cu fulgii de ovăz, ceapa rasă și stoarsă de zeamă, usturoiul, pătrunjelul tocat, sare și piper.", "Lasă compoziția 10 min: ovăzul absoarbe apa și chiftelele nu se mai sfărâmă.", "Formează bile de ~40 g cu mâinile ude și așază-le pe tavă cu hârtie de copt. 20–25 min, până sunt aurii. La cuptor, nu în tigaie — nu mai intră ulei în plus.", "Salata: roșii, castravete și ardei cuburi, ceapă roșie felii subțiri, oregano și ulei de măsline. Măslinele se pun în farfurie, nu în salata comună.", "Sosul: tahini cu lămâie și usturoi, subțiat cu apă rece lingură cu lingură, bătut până e cremos."], "sfat": "Ovăzul ține locul pesmetului și aduce fibre solubile în loc de amidon rafinat. Chiftelele din piept de pui, coapte, au aproximativ o treime din grăsimea celor din carne tocată grasă, prăjite. Salata grecească e fără brânză: masă cu carne.", "varianta": "Măslinele se pun în farfurie, nu în salata comună.", "total": {"k": 1415, "p": 99, "g": 50, "c": 145, "f": 17}, "vit": [{"n": "A", "v": "289", "u": "µg"}, {"n": "C", "v": "175", "u": "mg"}, {"n": "D", "v": "0", "u": "µg"}, {"n": "E", "v": "8.65", "u": "mg"}, {"n": "K", "v": "65.9", "u": "µg"}, {"n": "B6", "v": "4.06", "u": "mg"}, {"n": "Folat", "v": "196", "u": "µg"}, {"n": "B12", "v": "0.71", "u": "µg"}], "vitPartial": 0, "zile": ["Du1", "Lu2", "Du2"]}, {"id": "P11", "nume": "Mușchi de porc la grătar cu piure de broccoli și dovlecel, hrișcă și sos de roșii cu busuioc", "scurt": "Mușchi de porc cu piure de broccoli", "grup": "Feluri principale", "masa": "prânz/cină", "timp": "30′", "tine": "3 zile", "kcal": {"s": 615, "m": 690}, "macro": {"s": {"p": 51, "g": 19, "c": 68, "f": 14}, "m": {"p": 60, "g": 22, "c": 71, "f": 14}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Mușchi de porc", "s": "160 g", "m": "200 g", "sm": "360 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Broccoli", "s": "150 g", "m": "150 g", "sm": "300 g"}, {"nume": "Dovlecel", "s": "120 g", "m": "120 g", "sm": "240 g"}, {"nume": "Ceapă", "s": "30 g", "m": "30 g", "sm": "60 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Hrișcă", "s": "55 g", "m": "60 g", "sm": "115 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Roșii pasate", "s": "100 g", "m": "100 g", "sm": "200 g"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Ulei de măsline", "s": "8 g", "m": "10 g", "sm": "18 g"}, {"nume": "Semințe de dovleac", "s": "10 g", "m": "10 g", "sm": "20 g"}]}], "pasi": ["Pune hrișca la fiert: 1 parte la 2 de apă, 15 min cu capac, apoi 5 min deoparte. Dacă o prăjești uscat un minut înainte de a turna apa, capătă gust de alună.", "Fierbe broccoli și dovlecelul la abur 8 min — la abur, nu în apă, ca vitaminele să nu rămână în oală. Trebuie să iasă verzi, nu măslinii.", "Pasează-le cu jumătate din ulei, usturoi, un strop de lămâie și sare, până iese un piure verde, gros. Dacă e prea tare, o lingură din apa de la abur.", "Taie mușchiul medalioane de 2 cm și condimentează-l cu boia, cimbru, usturoi, sare și piper.", "Tigaia-grătar foarte încinsă: 3–4 min pe parte, fără să le miști. Apoi 5 min de odihnă.", "Sosul: roșiile pasate încălzite cu ceapa tocată mărunt și busuioc, 5 min, până se îngroașă. Semințele de dovleac, prăjite uscat 1 min, se presară peste piure la final."], "sfat": "Mușchiul de porc e una dintre cele mai slabe bucăți de carne roșie (sub 3 g grăsime la 100 g): se gătește repede, la foc mare, altfel se usucă. Piureul verde e legume, nu amidon — hrișca e cea care ține cei 20% din farfurie, iar ea aduce și magneziu și rutin.", "varianta": "Merge și cu cotlet de porc sau piept de pui. Piureul merge și din conopidă + mazăre.", "total": {"k": 1305, "p": 110, "g": 41, "c": 139, "f": 28}, "vit": [{"n": "A", "v": "169", "u": "µg"}, {"n": "C", "v": "337", "u": "mg"}, {"n": "D", "v": "0.72", "u": "µg"}, {"n": "E", "v": "10.4", "u": "mg"}, {"n": "K", "v": "334", "u": "µg"}, {"n": "B6", "v": "4.47", "u": "mg"}, {"n": "Folat", "v": "340", "u": "µg"}, {"n": "B12", "v": "1.84", "u": "µg"}], "vitPartial": 0, "zile": ["Lu2", "Ma2"]}, {"id": "P12", "nume": "Stir-fry de vită cu broccoli, ardei, ciuperci și varză, orez basmati, sos soia-ghimbir, caju", "scurt": "Stir-fry de vită", "grup": "Feluri principale", "masa": "prânz/cină", "timp": "25′", "tine": "2 zile", "kcal": {"s": 635, "m": 725}, "macro": {"s": {"p": 49, "g": 20, "c": 68, "f": 8}, "m": {"p": 60, "g": 24, "c": 73, "f": 8}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Vită slabă", "s": "150 g", "m": "190 g", "sm": "340 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Broccoli", "s": "100 g", "m": "100 g", "sm": "200 g"}, {"nume": "Ardei", "s": "70 g", "m": "70 g", "sm": "140 g"}, {"nume": "Ciuperci", "s": "50 g", "m": "50 g", "sm": "100 g"}, {"nume": "Varză", "s": "60 g", "m": "60 g", "sm": "120 g"}, {"nume": "Ceapă verde", "s": "20 g", "m": "20 g", "sm": "40 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Orez basmati", "s": "55 g", "m": "60 g", "sm": "115 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Sos de soia", "s": "15 ml", "m": "15 ml", "sm": "30 ml"}, {"nume": "Usturoi", "s": "3 g", "m": "3 g", "sm": "6 g"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Ulei de măsline", "s": "8 g", "m": "8 g", "sm": "16 g"}, {"nume": "Caju", "s": "15 g", "m": "20 g", "sm": "35 g"}]}], "pasi": ["Fierbe orezul basmati: 1 la 1,5 apă, capac, 12 min, plus 5 min deoparte.", "Pregătește tot înainte să aprinzi focul: vita fâșii subțiri tăiate contra fibrei, legumele tăiate, sosul de soia amestecat cu usturoiul și ghimbirul ras. Un stir-fry durează 8 minute — n-ai când să tai pe parcurs.", "Tigaia (sau wokul) foarte încinsă, un strop de ulei: vita, în strat subțire, 2 min, întoarsă o singură dată. Scoate-o.", "Restul de ulei: broccoli și ardeiul 3 min, apoi ciupercile și varza încă 2–3 min. Legumele trebuie să rămână crocante.", "Pune vita înapoi, toarnă sosul de soia cu usturoi și ghimbir și ține totul pe foc încă 1 min, cât se glazurează.", "Ceapa verde și caju, prăjit uscat, deasupra, la final."], "sfat": "Focul mare și timpul scurt păstrează legumele crocante și vitaminele hidrosolubile (C, din grupul B), care se pierd la fierbere lungă. Sosul de soia e sărat — cele 15 g aduc aproape un gram de sare, deci nu mai punem sare deloc în mâncare.", "varianta": "", "total": {"k": 1360, "p": 109, "g": 44, "c": 141, "f": 16}, "vit": [{"n": "A", "v": "315", "u": "µg"}, {"n": "C", "v": "413", "u": "mg"}, {"n": "D", "v": "0.2", "u": "µg"}, {"n": "E", "v": "7.74", "u": "mg"}, {"n": "K", "v": "411", "u": "µg"}, {"n": "B6", "v": "3.68", "u": "mg"}, {"n": "Folat", "v": "321", "u": "µg"}, {"n": "B12", "v": "6.3", "u": "µg"}], "vitPartial": 0, "zile": ["Mi2", "Jo2"]}, {"id": "P13", "nume": "Păstrăv la cuptor cu legume ratatouille, cartofi și sos de lămâie cu usturoi 🐟", "scurt": "Păstrăv cu ratatouille", "grup": "Feluri principale", "masa": "cină", "timp": "35′", "tine": "1 zi (rece)", "kcal": {"s": 615, "m": 715}, "macro": {"s": {"p": 45, "g": 22, "c": 62, "f": 11}, "m": {"p": 53, "g": 27, "c": 68, "f": 12}}, "comp": [{"eticheta": "Proteină", "items": [{"nume": "Păstrăv", "s": "180 g", "m": "220 g", "sm": "400 g"}]}, {"eticheta": "Legume", "items": [{"nume": "Vinete", "s": "80 g", "m": "80 g", "sm": "160 g"}, {"nume": "Dovlecel", "s": "80 g", "m": "80 g", "sm": "160 g"}, {"nume": "Ardei", "s": "60 g", "m": "60 g", "sm": "120 g"}, {"nume": "Ceapă", "s": "40 g", "m": "40 g", "sm": "80 g"}, {"nume": "Roșii", "s": "60 g", "m": "60 g", "sm": "120 g"}]}, {"eticheta": "Amidon", "items": [{"nume": "Cartofi", "s": "250 g", "m": "280 g", "sm": "530 g"}]}, {"eticheta": "Sos", "items": [{"nume": "Suc de lămâie", "s": "10 ml", "m": "10 ml", "sm": "20 ml"}, {"nume": "Usturoi", "s": "3 g", "m": "3 g", "sm": "6 g"}]}, {"eticheta": "Grăsimi", "items": [{"nume": "Ulei de măsline", "s": "10 g", "m": "12 g", "sm": "22 g"}]}], "pasi": ["Cuptorul la 200 °C. Cartofii feliați de 1 cm, cu jumătate din ulei, rozmarin și sare, pe tavă, 20 min.", "Taie vinetele, dovlecelul, ardeiul, ceapa și roșiile cuburi de 2 cm și amestecă-le cu restul de ulei, cimbru, sare și piper.", "Scoate tava, împinge cartofii într-o parte și adaugă legumele.", "Usucă păstrăvul, crestează-l, pune sare, piper, felii de lămâie și usturoi în burtă și așaz-l peste legume.", "Încă 15–18 min, până carnea peștelui e opacă și se desprinde ușor de os. Păstrăvul se face repede — mai mult îl usucă.", "Sosul: lămâie, ulei, usturoi pisat și mărar, bătute cu furculița și turnate peste pește în farfurie."], "sfat": "Peștele și legumele în aceeași tavă lucrează împreună: zeama legumelor ține peștele umed, iar grăsimea lui aromatizează legumele. Păstrăvul e, alături de doradă, sursa de omega-3 a săptămânii — de aceea se gătește proaspăt și blând, la cuptor, nu prăjit.", "varianta": "Se face ×2, proaspăt. Merge la fel cu chefal sau doradă. Ridichi — doar la cine le vrea.", "total": {"k": 1330, "p": 98, "g": 49, "c": 130, "f": 23}, "vit": [{"n": "A", "v": "592", "u": "µg"}, {"n": "C", "v": "333", "u": "mg"}, {"n": "D", "v": "63.6", "u": "µg"}, {"n": "E", "v": "15.8", "u": "mg"}, {"n": "K", "v": "52.5", "u": "µg"}, {"n": "B6", "v": "3.96", "u": "mg"}, {"n": "Folat", "v": "290", "u": "µg"}, {"n": "B12", "v": "17.2", "u": "µg"}], "vitPartial": 0, "zile": ["Ma2"]}];
